import assert from 'node:assert/strict';
import type {Page} from 'playwright';
import {waitForBrowserJson} from './browser-poll';
export async function verifyExploration(page:Page){
 const canvas=page.getByRole('region',{name:'Dashboard results',exact:true});
 await canvas.getByLabel('Filter preset name',{exact:true}).fill('Web only');await canvas.getByRole('button',{name:'Save current filters',exact:true}).click();await canvas.getByText('Filter preset saved.',{exact:true}).waitFor();
 await canvas.getByRole('button',{name:'Clear filters',exact:true}).click();await canvas.getByText('$350.00',{exact:true}).first().waitFor();await canvas.getByLabel('Saved filters',{exact:true}).selectOption({label:'Web only'});await canvas.getByRole('button',{name:'Apply saved filters',exact:true}).click();await canvas.getByText('$300.00',{exact:true}).first().waitFor();
 await canvas.getByRole('button',{name:'Inspect Revenue: Web',exact:true}).click();const records=canvas.getByRole('region',{name:'Matching source records',exact:true});await records.getByRole('cell',{name:'002',exact:true}).waitFor();await records.getByRole('cell',{name:'003',exact:true}).waitFor();assert.equal(await records.getByRole('row').count(),3);
 await canvas.getByRole('button',{name:'Hide source records',exact:true}).click();
 console.log('PASS: private saved filters and accessible chart-group source-record drilldown.');
}
export async function verifyMonitoringAndData(page:Page,origin:string,workspaceId:string,checkAccessibility:(page:Page,phase:string)=>Promise<void>){
 const base=origin+'/dashboard/app/workspaces/'+workspaceId;
 await page.setViewportSize({width:1280,height:900});await page.goto(base+'/monitoring');await page.getByLabel('Target name',{exact:true}).fill('Browser revenue goal');await page.getByLabel('Target dataset',{exact:true}).selectOption({label:'Browser orders'});await page.getByLabel('Target metric',{exact:true}).selectOption('REVENUE');await page.getByLabel('Target value',{exact:true}).fill('250');await page.getByLabel('Target starts',{exact:true}).fill('2026-01-01');await page.getByLabel('Target through',{exact:true}).fill('2026-01-03');await page.getByRole('button',{name:'Save target',exact:true}).click();await page.getByRole('heading',{name:'Browser revenue goal',exact:true}).waitFor();
 await page.getByRole('button',{name:'Edit target Browser revenue goal',exact:true}).click();await page.getByLabel('Target value',{exact:true}).fill('300');await page.getByRole('button',{name:'Save target',exact:true}).click();await page.getByText('Target saved.',{exact:true}).waitFor();
 await page.getByLabel('Alert name',{exact:true}).fill('Browser revenue alert');await page.getByLabel('Alert dataset',{exact:true}).selectOption({label:'Browser orders'});await page.getByLabel('Alert metric',{exact:true}).selectOption('REVENUE');await page.getByLabel('Alert target',{exact:true}).selectOption({label:'Browser revenue goal'});await page.getByRole('button',{name:'Save alert rule',exact:true}).click();await page.getByRole('button',{name:'Evaluate Browser revenue alert',exact:true}).waitFor();await page.getByRole('button',{name:'Evaluate Browser revenue alert',exact:true}).click();
 await waitForBrowserJson<{events:{status:string}[]}>(page,'/dashboard/app/api/workspaces/'+workspaceId+'/monitoring',value=>value.events.some(event=>event.status==='OPEN'),'Alert delivery');await page.getByRole('button',{name:'Refresh monitoring',exact:true}).click();await page.getByRole('button',{name:'Acknowledge Browser revenue alert',exact:true}).click();await page.getByText('Alert acknowledged.',{exact:true}).waitFor();await checkAccessibility(page,'targets-alerts-inbox');
 await page.getByRole('button',{name:'Edit alert Browser revenue alert',exact:true}).click();await page.getByLabel('Alert enabled',{exact:true}).uncheck();await page.getByRole('button',{name:'Save alert rule',exact:true}).click();await page.getByText('Alert rule saved.',{exact:true}).waitFor();
 await page.goto(base+'/data');await page.getByLabel('Dataset to manage',{exact:true}).selectOption({label:'Browser orders'});await page.getByRole('table',{name:'Source field profile',exact:true}).waitFor();await page.getByLabel('Transformation field',{exact:true}).selectOption('channel');await page.getByRole('button',{name:'Add transformation step',exact:true}).click();await page.getByRole('button',{name:'Create cleaned version',exact:true}).click();await page.getByText('Transformation queued.',{exact:false}).waitFor();
 await waitForBrowserJson<{datasets:{name:string;pendingVersionId:string|null;metricConfirmationRequired:boolean}[]}>(page,'/dashboard/app/api/workspaces/'+workspaceId+'/datasets',value=>value.datasets.some(dataset=>dataset.name==='Browser orders'&&!dataset.pendingVersionId&&dataset.metricConfirmationRequired),'Cleaned version profiling');
 await page.getByLabel('Inactive version retention (days)',{exact:true}).fill('30');await page.getByLabel('Archived dataset retention (days)',{exact:true}).fill('90');await page.getByLabel('Legal hold',{exact:true}).check();await page.getByRole('button',{name:'Save retention policy',exact:true}).click();await page.getByText('Retention policy saved.',{exact:true}).waitFor();await page.reload();await page.getByLabel('Inactive version retention (days)',{exact:true}).waitFor();await page.waitForFunction(()=>{const control=document.querySelector('input[type="checkbox"]') as HTMLInputElement;return control?.checked;});
 assert.equal(await page.getByLabel('Inactive version retention (days)',{exact:true}).inputValue(),'30');await checkAccessibility(page,'data-cleaning-retention');
 await page.getByLabel('Dataset to manage',{exact:true}).selectOption({label:'Browser orders'});page.once('dialog',dialog=>dialog.accept());await page.getByRole('button',{name:'Archive selected dataset',exact:true}).click();await page.getByText('Dataset archived.',{exact:true}).waitFor();
 await page.setViewportSize({width:390,height:844});await checkAccessibility(page,'data-management-mobile');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'Data management page overflows mobile viewport');
 console.log('PASS: target create/edit, dataset-bound alerts, real evaluation/inbox/acknowledgement, rule disable, transformation, retention/legal hold and archive.');
}
